-- ==========================================
-- HEY YOUTH! — Supabase Field Stories Patch
-- Adds field_stories table for Volunteer Stories & Field Notes
-- ==========================================

CREATE TABLE IF NOT EXISTS public.field_stories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category VARCHAR(100) NOT NULL, -- 'kolong', 'mentoring', 'bts', 'expedition', 'testimonial'
    category_label_id VARCHAR(100) NOT NULL,
    category_label_en VARCHAR(100) NOT NULL,
    read_time_id VARCHAR(50) NOT NULL,
    read_time_en VARCHAR(50) NOT NULL,
    date_id VARCHAR(100) NOT NULL,
    date_en VARCHAR(100) NOT NULL,
    author_name VARCHAR(255) NOT NULL,
    author_role_id VARCHAR(255) NOT NULL,
    author_role_en VARCHAR(255) NOT NULL,
    author_avatar TEXT,
    image TEXT,
    title_id TEXT NOT NULL,
    title_en TEXT NOT NULL,
    excerpt_id TEXT NOT NULL,
    excerpt_en TEXT NOT NULL,
    quote_id TEXT NOT NULL,
    quote_en TEXT NOT NULL,
    content_id TEXT NOT NULL,
    content_en TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::text, NOW()) NOT NULL
);

-- Enable RLS
ALTER TABLE public.field_stories ENABLE ROW LEVEL SECURITY;

-- Policies for public select and full CMS access
DROP POLICY IF EXISTS "Allow public select on field_stories" ON public.field_stories;
CREATE POLICY "Allow public select on field_stories" ON public.field_stories
    FOR SELECT TO public USING (true);

DROP POLICY IF EXISTS "Allow public insert on field_stories" ON public.field_stories;
CREATE POLICY "Allow public insert on field_stories" ON public.field_stories
    FOR INSERT TO public WITH CHECK (true);

DROP POLICY IF EXISTS "Allow public update on field_stories" ON public.field_stories;
CREATE POLICY "Allow public update on field_stories" ON public.field_stories
    FOR UPDATE TO public USING (true);

DROP POLICY IF EXISTS "Allow public delete on field_stories" ON public.field_stories;
CREATE POLICY "Allow public delete on field_stories" ON public.field_stories
    FOR DELETE TO public USING (true);

-- Seed initial 5 stories (including Testimonial category)
INSERT INTO public.field_stories (
    id, category, category_label_id, category_label_en, read_time_id, read_time_en, date_id, date_en,
    author_name, author_role_id, author_role_en, author_avatar, image,
    title_id, title_en, excerpt_id, excerpt_en, quote_id, quote_en, content_id, content_en
) VALUES
(
    501, 'kolong', 'Sekolah Kolong', 'Street Schools', '3 min baca', '3 min read', '14 Okt 2025', 'Oct 14, 2025',
    'Salsabila Azzahra', 'Teacher Volunteer • Batch 4 (Chapter Jakarta)', 'Teacher Volunteer • Batch 4 (Jakarta Chapter)',
    'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&h=150&fit=crop&crop=face',
    'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?q=80&w=800&auto=format&fit=crop',
    'Melihat Binar Harapan di Kolong Jembatan Ciputat', 'Seeing Glimmers of Hope Under the Ciputat Flyover',
    'Hari pertama mengajar diiringi gemuruh suara knalpot dan kepulan asap. Tapi ketika adik-adik berebut mengangkat tangan menjawab soal perkalian, rasa lelah seketika sirna.',
    'Teaching on the first day was accompanied by loud engine roars and exhaust smoke. But the moment the children eagerly raised their hands to solve math, all exhaustion disappeared.',
    '"Bagi adik-adik di sini, kehadiran relawan adalah bukti nyata bahwa mimpi-mimpi mereka tidak pernah dilupakan."',
    '"For these kids, our volunteer presence is living proof that their dreams are never forgotten."',
    'Pagi itu di TBM Kolong Ciputat, debu jalanan beterbangan tertiup angin lalu lintas. Sekitar 25 adik-adik duduk beralaskan terpal tipis dengan pensil pendek yang sudah diraut berkali-kali.\n\nAwalnya kami khawatir materi matematika dasar akan membosankan bagi mereka. Namun begitu kami mengubahnya menjadi permainan kuis interaktif dengan tepuk tangan berirama, suasana berubah 180 derajat. Seorang adik bernama Alif (9 tahun) menarik ujung baju saya dan berbisik: "Kak Salsa, minggu depan datang lagi ya? Aku mau diajarin baca dongeng petualangan."\n\nDi saat itulah saya menyadari: pendidikan bukan sekadar angka di atas lembar raport. Bagi anak-anak di sini, kehadiran relawan adalah jendela bahwa dunia luar begitu luas dan impian mereka patut diperjuangkan.',
    'That morning at TBM Kolong Ciputat, street dust blew across the busy highway traffic. About 25 young children sat on thin tarpaulins holding short pencils sharpened many times over.\n\nInitially, we worried basic mathematics would bore them. But as soon as we gamified it into an energetic rhythm quiz with cheerful claps, the atmosphere shifted completely. A young boy named Alif (9 years old) tugged my sleeve and whispered: "Teacher Salsa, please come back next week? I want to learn adventure storytelling."\n\nThat was when I truly realized: education isn''t just grades on a report card. For these kids, our volunteer presence is a wide open window proving that the world is limitless and their dreams are worth fighting for.'
),
(
    502, 'bts', 'Di Balik Layar', 'Behind The Scenes', '2 min baca', '2 min read', '28 Sep 2025', 'Sep 28, 2025',
    'Rian Pratama', 'Graphic Designer & Media (Chapter Bandung)', 'Graphic Designer & Media (Bandung Chapter)',
    'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=150&h=150&fit=crop&crop=face',
    'https://images.unsplash.com/photo-1531482615713-2afd69097998?q=80&w=800&auto=format&fit=crop',
    'Dari Kanvas Digital ke Senyum Nyata: Cerita Tim Kreatif', 'From Digital Canvas to Pure Smiles: The Creative Journey',
    'Sering dikira hanya berkutat dengan laptop dan revisi warna. Tapi saat turun langsung memotret tawa adik-adik saat menerima buku baru, setiap desain poster terasa punya nyawa.',
    'People often assume creative volunteers just sit behind laptops dealing with color revisions. But documenting the raw joy of children receiving brand new books gave our designs true heartbeat.',
    '"Satu desain visual yang dikerjakan dengan tulus bisa menggerakkan ratusan hati untuk ikut peduli dan berbagi."',
    '"A single visual design crafted with genuine empathy can inspire hundreds of hearts to care and contribute."',
    'Sebagai relawan divisi kreatif, rutinitas kami biasanya berkisar pada deadline poster Instagram, pemilihan tipografi, dan render video di larut malam. Kadang muncul rasa jenuh: apakah karya-karya ini benar-benar membawa perubahan nyata?\n\nSemua keraguan itu terjawab ketika saya ikut turun langsung ke lapangan saat pembagian donasi buku dan perlengkapan sekolah di Bandung Timur. Kamera saya menangkap momen seorang anak perempuan memeluk buku cerita bergambar dengan mata berbinar.\n\nWajah polosnya mengingatkan saya mengapa kami begadang mendesain konten kampanye: karena satu desain yang menggugah bisa mendatangkan ratusan donatur yang mengubah masa depan anak-anak ini.',
    'As creative volunteers, our routine usually revolves around Instagram deadlines, font pairing, and late-night video renders. Sometimes self-doubt creeps in: do these visuals truly make a tangible difference?\n\nThat doubt evaporated when I joined the field team distributing books and stationery sets in East Bandung. Through my camera lens, I captured a young girl clutching an illustrated storybook with sparkling eyes.\n\nHer innocent smile reminded me why we burned the midnight oil crafting campaign visuals: because one touching design can rally hundreds of donors who transform these kids'' futures.'
),
(
    503, 'mentoring', 'Mentoring & Karir', 'Mentorship', '3 min baca', '3 min read', '19 Agt 2025', 'Aug 19, 2025',
    'Dimas Wahyudi', 'Mentoring Tutor (Chapter Depok)', 'Mentoring Tutor (Depok Chapter)',
    'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=150&h=150&fit=crop&crop=face',
    'https://images.unsplash.com/photo-1577896851231-70ef18881754?q=80&w=800&auto=format&fit=crop',
    'Mendampingi Mimpi Pertama: Dari Pemalu Menjadi Juara Kelas', 'Mentoring the First Dream: From Shy Corner to Top of the Class',
    'Riko (11 tahun) awalnya selalu menunduk saat diajak bicara. Lewat 3 bulan bimbingan personal yang sabar, minggu lalu ia berani maju dan berkata: "Kak, aku mau jadi programmer!".',
    'Riko (11) used to stare at the floor whenever spoken to. After 3 months of patient 1-on-1 mentorship, he stood tall in front of the class: "Kak, I want to be a software developer!".',
    '"Terkadang seorang anak hanya membutuhkan satu orang dewasa yang benar-benar percaya pada potensi mereka."',
    '"Sometimes a child only needs one caring mentor who genuinely believes in their hidden potential."',
    'Dalam program Teacher Class & Mentoring Hey Youth, setiap relawan memegang 3 sampai 4 adik asuh untuk didampingi secara intensif. Salah satu adik asuh saya, Riko, mengalami krisis percaya diri karena sering diejek lambat membaca di sekolah asalnya.\n\nKuncinya bukan memaksanya menghafal rumus, melainkan mendengarkan apa yang sebenarnya ia sukai. Ketika saya mengetahui ia suka mobil-mobilan dan puzzle, kami belajar logika matematika melalui analogi lintasan balap dan susun balok.\n\nTiga bulan kemudian, ibunya menghubungi saya sambil menangis haru: Riko meraih peringkat 3 besar di kelasnya dan terpilih menjadi perwakilan lomba cerdas cermat tingkat kelurahan.',
    'In Hey Youth''s Teacher Class & Mentorship program, each volunteer mentors 3 to 4 students intensively. One of my mentees, Riko, struggled with self-esteem because classmates teased him for reading slowly.\n\nThe breakthrough didn''t come from forcing formulas, but by listening to his passions. When I discovered he loved toy cars and logic puzzles, we learned math principles through race track analogies and puzzle building.\n\nThree months later, his mother called me in tears of joy: Riko earned top 3 in his class and was chosen for the inter-district quiz competition.'
),
(
    504, 'expedition', 'Ekspedisi Daerah', 'Regional Expedition', '4 min baca', '4 min read', '05 Jul 2025', 'Jul 05, 2025',
    'Amanda Nurul & Tim Koordinator', 'Community Coordinator (Chapter Banten)', 'Community Coordinator (Banten Chapter)',
    'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=150&h=150&fit=crop&crop=face',
    'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?q=80&w=800&auto=format&fit=crop',
    'Menembus Pelosok: Menyalakan Lentera Literasi di Banten Selatan', 'Reaching Remote Corners: Igniting Literacy in South Banten',
    'Jalan tanah terjal sepanjang 5 jam seketika terlupakan saat melihat 40 pasang kaki kecil berlari riang menyambut mobil logistik kami. Mereka tidak kekurangan mimpi, mereka hanya butuh akses yang setara.',
    'A 5-hour bumpy dirt road trek was instantly forgotten upon seeing 40 pairs of little bare feet running ecstatically to greet our logistics van. They never lacked ambition; they just needed equal access.',
    '"Batas geografis dan jalan terjal tidak boleh menjadi penghalang bagi tingginya impian anak-anak Indonesia."',
    '"Geographical borders and rugged trails must never cap the aspirations of our nation''s children."',
    'Desa Cikadu di Banten Selatan terletak cukup jauh dari pusat kota dengan fasilitas perpustakaan yang hampir tidak ada. Listrik masih sering padam bergantian dan sinyal ponsel sangat minim. Bersama 12 relawan Hey Youth, kami membawa 5 kardus buku ensiklopedia, proyektor tenaga baterai, dan alat-alat peraga sains sederhana.\n\nSelama dua hari di sana, balai desa disulap menjadi laboratorium sains mini. Anak-anak melihat reaksi gunung meletus dari baking soda dan cuka untuk pertama kalinya dengan mata terbelalak kagum.\n\nMalam harinya, di bawah langit berbintang, kami memutar film dokumenter luar angkasa. Salah satu anak, Deden, berkata: "Ternyata bumi itu bulat dan ada bintang sebesar matahari ya Kak? Aku mau belajar yang rajin biar bisa naik pesawat luar angkasa." Pengalaman ini membuktikan bahwa batas geografis tidak boleh membatasi tingginya impian seorang anak Indonesia.',
    'Cikadu village in South Banten lies tucked deep away with virtually zero library access. Electricity experiences frequent blackouts and cellular signals are scarce. Together with 12 Hey Youth volunteers, we brought 5 boxes of illustrated encyclopedias, a battery-powered projector, and simple science props.\n\nOver two days, the village hall became a buzzing science laboratory. The kids watched a baking soda volcano erupt with pure awe and wonder.\n\nThat evening under the starry sky, we screened an astronomy documentary. A boy named Deden smiled: "So the earth is round and there are stars bigger than the sun? I will study hard so one day I can ride a spacecraft." This trip proved that geographic boundaries must never limit the heights of an Indonesian child''s dream.'
),
(
    505, 'testimonial', 'Testimonial', 'Testimonial', '2 min baca', '2 min read', '22 Okt 2025', 'Oct 22, 2025',
    'Nadia Safitri', 'Volunteer Alumni & Mentor Batch 3', 'Volunteer Alumni & Mentor Batch 3',
    'https://images.unsplash.com/photo-1517841905240-472988babdf9?w=150&h=150&fit=crop&crop=face',
    'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?q=80&w=800&auto=format&fit=crop',
    'Testimonial Relawan: Menemukan Makna dan Sahabat Seperjuangan', 'Volunteer Testimonial: Finding Purpose and Lifelong Comrades',
    'Bergabung dengan Hey Youth mengubah cara pandang saya tentang kepemimpinan. Di sini saya tidak hanya memberi, tetapi justru belajar banyak tentang ketulusan dan empati.',
    'Joining Hey Youth fundamentally transformed how I view leadership. Here I didn''t just give, but learned so much about genuine sincerity and empathy.',
    '"Hey Youth adalah ruang bertumbuh terbaik bagi pemuda yang ingin aksi nyata, bukan sekadar wacana."',
    '"Hey Youth is the ultimate growth hub for young people who crave real action, not just talk."',
    'Saat pertama kali mendaftar sebagai relawan, saya hanya berniat mengisi waktu luang semester akhir kuliah. Namun atmosfer kekeluargaan dan dedikasi rekan-rekan relawan di Hey Youth sangat menular. Setiap minggunya kami berdiskusi, merancang kurikulum kreatif, dan terjun bersama ke lapangan.\n\nPengalaman ini mengasah kepemimpinan, komunikasi, dan resiliensi saya jauh lebih dalam dibandingkan materi kuliah di kelas. Hey Youth membuktikan bahwa pemuda memiliki kekuatan luar biasa jika bergerak bersama demi masa depan pendidikan Indonesia.',
    'When I first applied as a volunteer, I merely intended to spend my spare final semester time. But the warm camaraderie and relentless dedication of the Hey Youth team was deeply contagious. Every single week we brainstormed, designed creative curriculum, and ventured to the field together.\n\nThis journey sharpened my leadership, communication, and resilience far deeper than any textbook lecture could. Hey Youth proves that youth possess extraordinary power when united for the future of education.'
)
ON CONFLICT (id) DO NOTHING;
